"""Invalid-image detection: mutate a valid image and require load to fail."""
import json, os, random, subprocess, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import norm, lpm, build_image

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

def run(payload):
    r = subprocess.run([sys.executable, os.path.join(ROOT,'run.py')],
                       input=json.dumps(payload).encode(), capture_output=True, cwd=ROOT)
    if r.returncode != 0: raise RuntimeError(r.stderr[:400].decode())
    return json.loads(r.stdout.decode())

def w2i(w): return int(w, 16)
def i2w(v): return '%064x' % (v & ((1 << 256) - 1))

def getf(img, stage, row, bitoff, n):
    v = w2i(img['banks'][stage][row])
    return (v >> (bitoff)) & ((1 << n) - 1 if n < 64 else (1<<64)-1)

def setf(img, stage, row, bitoff, n, val):
    v = w2i(img['banks'][stage][row])
    m = ((1 << n) - 1 if n < 64 else (1<<64)-1) << bitoff
    v = (v & ~m) | ((val << bitoff) & m)
    img['banks'][stage][row] = i2w(v)

def cells_row(img, stage, cell): return cell // 2, 128 * (cell % 2)

rng = random.Random(4242)
fib = {}
for _ in range(60):
    a = '%032x' % rng.getrandbits(128)
    l = rng.choice([0, 16, 17, 20, 33, 48, 64, 65, 70, 100, 128, rng.randint(0,128)])
    fib[(norm(a,l), l)] = rng.randint(0, 4194302)
img0 = build_image(fib)

# sanity: unmutated image is accepted
ops = [["load", img0], ["image_query", ["20010db8000000010000000000000001"]]]
r = run({"cases":[{"ops":ops}]})
assert r['results'][0]['loads'] == [True], r['results'][0]['loads']

def node_cells(img):
    """All (stage,row,bitoff,type) records from a BFS-free guess: every cell that
    starts a record.  We discover them by scanning: use the canonical graph sizes."""
    return None

mutations = []

def mut(name, fn):
    mutations.append((name, fn))

# --- field level mutations on the first record we can find
def first_record(img):
    for s in range(11):
        if img['banks'][s]:
            return s, 0, 0
    return None

# 1: bad type
def m_type(img):
    s, row, off = first_record(img)
    t = getf(img, s, row, off, 3)
    setf(img, s, row, off, 3, 0 if t != 0 else 6)
mut('type-field', m_type)

# 2: reserved bit set
def m_reserved(img):
    s, row, off = first_record(img)
    t = getf(img, s, row, off, 3)
    if t in (1,4): setf(img, s, row, off+119, 1, 1)
    elif t == 2: setf(img, s, row, off+255, 1, 1)
    elif t == 3: setf(img, s, row, off+249, 7, 0x7f)
    else: setf(img, s, row, off+213, 43, 1)
mut('reserved-bits', m_reserved)

# 3: wrong BMP
def m_bmp(img):
    s, row, off = first_record(img)
    b = getf(img, s, row, off+3, 22)
    setf(img, s, row, off+3, 22, (b + 1) % 4194303)
mut('bmp-value', m_bmp)

# 4: hop changed in an inline prefix (fragment hop at bit 97)
def m_hop(img):
    for s in range(11):
        for r, w in enumerate(img['banks'][s]):
            t = getf(img, s, r, 0, 3)
            if t == 4:
                h = getf(img, s, r, 97, 22)
                if h != 4194302:
                    setf(img, s, r, 97, 22, h + 1)
                    return
    raise Skip()
mut('inline-hop', m_hop)

# 5: inline hop = null marker
def m_hopnull(img):
    for s in range(11):
        for r, w in enumerate(img['banks'][s]):
            if getf(img, s, r, 0, 3) == 4:
                setf(img, s, r, 97, 22, 4194303)
                return
    raise Skip()
mut('inline-hop-null', m_hopnull)

# 6: fragment host bits
def m_hostbits(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) == 4:
                rel = getf(img, s, r, 89, 8)
                if rel < 63:
                    setf(img, s, r, 25 + rel, 1, 1)
                    return
    raise Skip()
mut('fragment-host-bits', m_hostbits)

# 7: bad relative length
def m_rel(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) == 4:
                rel = getf(img, s, r, 89, 8)
                setf(img, s, r, 89, 8, rel + 64)
                return
    raise Skip()
mut('relative-length', m_rel)

# 8: drop a front entry
def m_front_drop(img):
    if img['front16']:
        img['front16'].pop(0); return
    if img['front64']: img['front64'].pop(0); return
    raise Skip()
mut('front-incomplete', m_front_drop)

# 9: bogus extra front
def m_front_extra(img):
    img['front16'].append(["ffff", 0, 0])
mut('front-extra', m_front_extra)

# 10: unsorted fronts
def m_front_unsorted(img):
    if len(img['front16']) > 1:
        img['front16'][0], img['front16'][1] = img['front16'][1], img['front16'][0]; return
    if len(img['front64']) > 1:
        img['front64'][0], img['front64'][1] = img['front64'][1], img['front64'][0]; return
    raise Skip()
mut('front-unsorted', m_front_unsorted)

# 11: duplicate front key
def m_front_dup(img):
    if img['front16']:
        img['front16'].append(list(img['front16'][0])); return
    raise Skip()
mut('front-duplicate', m_front_dup)

# 12: dictionary pattern unused (append a duplicate-free extra pattern)
def m_dict_extra(img):
    used = set()
    for s in range(11):
        for r in range(len(img['banks'][s])):
            t = getf(img, s, r, 0, 3)
            if t in (1,2,3) and (s, r, 0) is not None:
                pass
    pats = set(int(x,16) for x in img['bitmaps'])
    for cand in range(1, 64):
        if cand not in pats:
            img['bitmaps'].append('%016x' % cand); return
    raise Skip()
mut('dictionary-unused-pattern', m_dict_extra)

# 13: unsorted dictionary
def m_dict_unsorted(img):
    if len(img['bitmaps']) > 1:
        img['bitmaps'][0], img['bitmaps'][1] = img['bitmaps'][1], img['bitmaps'][0]
mut('dictionary-unsorted', m_dict_unsorted)

# 14: NI tiling hole (bump the first used base)
def m_ni_base(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) in (1,2,3):
                b = getf(img, s, r, 41, 22)
                if b > 0:
                    setf(img, s, r, 41, 22, b + 1); return
    raise Skip()
mut('ni-base-hole', m_ni_base)

# 15: NI out of range
def m_ni_range(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) in (1,2,3):
                setf(img, s, r, 41, 22, 8191); return
    raise Skip()
mut('ni-base-range', m_ni_range)

# 16: bank row count mismatch
def m_bank_size(img):
    for s in range(11):
        if img['banks'][s]:
            img['banks'][s].append('0'*64); return
    raise Skip()
mut('bank-rows', m_bank_size)

# 17: cells count too small
def m_cells(img):
    for s in range(11):
        if img['cells'][s] > 0:
            img['cells'][s] -= 1
            img['banks'][s] = img['banks'][s][:(img['cells'][s]+1)//2]
            return
    raise Skip()
mut('cells-truncate', m_cells)

# 18: child stage >= parent stage
def m_child_stage(img):
    for s in range(10, -1, -1):
        for r in range(len(img['banks'][s])):
            t = getf(img, s, r, 0, 3)
            if t in (1,2):
                setf(img, s, r, 63, 4, s); return
            if t == 3:
                setf(img, s, r, 149, 4, s); return
    raise Skip()
mut('child-stage-not-lower', m_child_stage)

# 19: NI bitmap bit0 set
def m_ni_bit0(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) in (1,2,3):
                b = getf(img, s, r, 25, 16)
                p = int(img['bitmaps'][b], 16)
                if p == 0:
                    img['bitmaps'][b] = '%016x' % 1
                    return
                img['bitmaps'][b] = '%016x' % (p | 1)
                return
    raise Skip()
mut('ni-bit0', m_ni_bit0)

# 20: two records swapped (structure mismatch) - swap two rows in the same stage
def m_swap(img):
    for s in range(11):
        if len(img['banks'][s]) >= 2:
            img['banks'][s][0], img['banks'][s][1] = img['banks'][s][1], img['banks'][s][0]
            return
    raise Skip()
mut('row-swap', m_swap)

# 21: root locator into empty stage
def m_root(img):
    if img['root'] is not None:
        img['root'] = [0, 0]
        return
    raise Skip()
mut('root-locator', m_root)

# 22: nonzero padding of the final half row
def m_pad(img):
    for s in range(11):
        if img['cells'][s] % 2 == 1 and img['banks'][s]:
            v = w2i(img['banks'][s][-1])
            img['banks'][s][-1] = i2w(v | 1)
            return
    raise Skip()
mut('padding-nonzero', m_pad)

# 23: TYPE3 bulk base odd
def m_bulk_base(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) == 3:
                b = getf(img, s, r, 127, 22)
                if b > 0:
                    setf(img, s, r, 127, 22, b - 1); return
    raise Skip()
mut('bulk-base-odd', m_bulk_base)

# 24: absent encoding not last / present after absent
def m_absent(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            t = getf(img, s, r, 0, 3)
            if t in (1,2):
                n = 2 if t == 1 else 6
                for i in range(n):
                    if getf(img, s, r, 63 + 32*i, 32) == (15 << 6):
                        setf(img, s, r, 63 + 32*i, 32, (15 << 6) | 1)
                        return
    raise Skip()
mut('absent-encoding', m_absent)

class Skip(Exception): pass

results = []
for name, fn in mutations:
    img = json.loads(json.dumps(img0))
    try:
        fn(img)
    except Skip:
        results.append((name, 'skip')); continue
    except BaseException as e:
        results.append((name, 'error %s' % e)); continue
    r = run({"cases":[{"ops":[["load", img], ["image_query", ["20010db8000000010000000000000001"]]]}]})
    got = r['results'][0]['loads']
    results.append((name, 'REJECTED' if got == [False] else 'ACCEPTED!!'))
bad = 0
for name, st in results:
    print('%-28s %s' % (name, st))
    if st.startswith('ACCEPTED'): bad += 1
print('accepted-but-should-fail:', bad)
sys.exit(1 if bad else 0)
